-- +goose Up
-- Seed verified Gem-hosted (https://jobs.gem.com/<slug>) careers boards.
--
-- Generated 2026-05-15. Source list verified against:
--   1. Gem Job Board API     -> https://api.gem.com/job_board/v0/<slug>/job_posts/  (must return 200)
--   2. Gem public SPA page   -> https://jobs.gem.com/<slug>                          (must return 200)
-- Slugs failing either check were excluded. The 'conductorai' slug already exists
-- in migration 039 (ashby) and is intentionally not re-seeded here to preserve
-- adapter history; admins can switch its adapter via the admin UI if desired.
--
-- Companies count: 253.
-- Display names + logo URLs come from each board's <title> + og:image meta tags.
-- Gem's default placeholder logo (gem.com/img/gem-logotype-*) is stored as NULL.
--
-- Schema notes (post-044):
--   companies              (id, name, slug, website, careers_url, logo_url)
--   company_scan_settings  (company_id, adapter_type, active)
--   Adapter type 'gem' is registered in adapter_configs via migration 050.

ON CONFLICT (id) DO UPDATE SET
    name        = EXCLUDED.name,
    slug        = EXCLUDED.slug,
    website     = EXCLUDED.website,
    careers_url = EXCLUDED.careers_url,
    logo_url    = COALESCE(EXCLUDED.logo_url, companies.logo_url),
    updated_at  = NOW();

ON CONFLICT (company_id) DO UPDATE SET
    adapter_type = EXCLUDED.adapter_type,
    active       = EXCLUDED.active;

-- +goose Down
